const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/action_plans/plan_template_sections',
  headers: {'content-type': 'application/json'},
  body: {
    plan_template_section: {plan_template_id: 42, title: 'A new Company Action Plan Template Section'}
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/companies/%7Bcompany_id%7D/action_plans/plan_template_sections"),
    Content = new StringContent("{\"plan_template_section\":{\"plan_template_id\":42,\"title\":\"A new Company Action Plan Template Section\"}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

